/**
 * Deterministic pseudo-random rotation and translation based on claim string hash.
 * Ensures the same claim lands consistently on reloads, but different claims vary naturally.
 * Rotation range: -8deg to +8deg.
 * Offset range: ±2-3px x/y.
 */
function getStampTransform(claimText) {
  let hash = 0;
  for (let i = 0; i < claimText.length; i++) {
    hash = ((hash << 5) - hash) + claimText.charCodeAt(i);
    hash |= 0;
  }
  const absHash = Math.abs(hash);

  // Rotation between -8deg and +8deg
  let rot = (absHash % 17) - 8;
  if (rot === 0) rot = (absHash % 2 === 0) ? 4 : -4;

  // Offset X: -2.5px to +2.5px
  const offsetX = (((absHash >> 2) % 6) - 2.5).toFixed(1);

  // Offset Y: -2px to +2px
  const offsetY = (((absHash >> 4) % 5) - 2).toFixed(1);

  return `rotate(${rot}deg) translate(${offsetX}px, ${offsetY}px)`;
}

