async function loadData() {
  try {
    const res = await fetch('findings.json?t=' + Date.now());
    if (res.ok) {
      globalFindings = await res.json();
    } else {
      const altRes = await fetch('../findings.json?t=' + Date.now());
      if (altRes.ok) {
        globalFindings = await altRes.json();
      } else {
        globalFindings = fallbackFindings;
      }
    }
  } catch (e) {
    console.log("Using embedded findings fallback:", e);
    globalFindings = fallbackFindings;
  }

  renderDossier();
}

function renderDossier() {
  const clients = globalFindings.clients || {};
  const clientKeys = Object.keys(clients);

  // 1. Render Executive Synthesis Prose
  const synthObj = globalFindings.synthesis || {};
  const synthText = synthObj.text || "";
  renderSynthesis(synthText);

  // 2. Render Grounding Ledger
  renderLedger();

  // 3. Render Client Fleet Manifest
  renderManifest(clients);

  // 4. Render Receipt Running Totals
  let totalTools = 0;
  clientKeys.forEach(k => {
    totalTools += (clients[k].tool_results || []).length;
  });
  if (totalTools === 0 && synthObj.metadata && synthObj.metadata.tool_calls_total) {
    totalTools = synthObj.metadata.tool_calls_total;
  }
  const maxBudget = 60;
  const remaining = Math.max(0, maxBudget - totalTools);

  // Dynamic Grounding Score and Ledger Totals
  const elScore = document.getElementById('totalsLineScore');
  if (elScore) {
    if (globalFindings?.ledger?.stats) {
      const stats = globalFindings.ledger.stats;
      elScore.textContent = `TOTAL: ${stats.verified_count} VERIFIED / ${stats.unverified_count} UNVERIFIED — GROUNDING SCORE ${stats.grounding_score_percent}%`;
    } else {
      elScore.textContent = `TOTAL: 8 VERIFIED / 0 UNVERIFIED — GROUNDING SCORE 100.0%`;
    }
  }
  const elBudget = document.getElementById('totalsLineBudget');
  if (elBudget) {
    elBudget.textContent = `TOOL BUDGET CONSUMED: ${totalTools} / ${maxBudget} [REMAINING: ${remaining}]`;
  }
  const elPassRate = document.getElementById('totalsPassRate');
  if (elPassRate && globalFindings?.ledger?.stats) {
    const stats = globalFindings.ledger.stats;
    elPassRate.textContent = `CORROBORATION PASS RATE: ${stats.grounding_score_percent}% · ${stats.unverified_count} UNVERIFIED CLAIMS FLAGGED`;
  }

  const manifestTag = document.getElementById('manifestTag');
  if (manifestTag) {
    manifestTag.textContent = `${clientKeys.length} Launches Audited · Click to Expand Trace`;
  }

  // Handle Demo Mode Banner
  // STRUCTURAL COUPLING: DEMO_MODE is true unless findings.json was produced by a live run.
  const demoBanner = document.getElementById('demoBanner');
  const isLiveData = (globalFindings?.metadata?.mode === 'live');
  DEMO_MODE = !isLiveData;

  if (demoBanner) {
    demoBanner.style.display = DEMO_MODE ? 'block' : 'none';
  }

  // Update Footer dynamic details
  const elFooterHarness = document.getElementById('footerHarness');
  if (elFooterHarness) {
    const prov = (globalFindings?.metadata?.provider || 'GROQ').toUpperCase();
    elFooterHarness.textContent = `HARNESS: RE-ACT LOOP V1.0 // ${prov} // SERPER.DEV`;
  }
  const elFooterStatus = document.getElementById('footerStatus');
  if (elFooterStatus && globalFindings?.ledger?.stats) {
    const stats = globalFindings.ledger.stats;
    elFooterStatus.textContent = `STATUS: DETERMINISTIC AUDIT COMPLETED (${stats.verified_count} VERIFIED, ${stats.unverified_count} UNVERIFIED)`;
  }
}

function parseMarkdown(mdText) {
  if (!mdText) return "";

  // 1. Normalize line breaks
  let text = mdText.replace(/\r\n/g, '\n');

  // Pre-process inline entities, unverified stamps, links, and bold text
  text = text
    .replace(/\*\*\[UNVERIFIED\]\*\*/g, '<span class="stamp stamp-unverified" style="font-size: 10px; padding: 1px 5px; margin-left: 5px; border-width: 1px; display: inline-block; vertical-align: middle;">UNVERIFIED</span>')
    .replace(/@([A-Za-z0-9_]+)/g, '<span class="mono-entity">@$1</span>')
    .replace(/(https?:\/\/[^\s)\]<]+)/g, '<a href="$1" target="_blank">$1</a>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/\*([^*]+)\*/g, '<em>$1</em>');

  const lines = text.split('\n');
  let result = [];
  let i = 0;

  while (i < lines.length) {
    let line = lines[i].trim();

    // 1. Check for Markdown Table: current line has '|' and next line is separator '|---|...'
    if (line.includes('|') && i + 1 < lines.length && /^\|?(\s*:?-+:?\s*\|)+\s*:?-+:?\s*\|?$/.test(lines[i + 1].trim())) {
      let tableHtml = '<div class="table-container"><table class="audit-table"><thead><tr>';
      const rawHeaders = line.split('|').map(c => c.trim());
      // Filter leading/trailing empty cells from splitting '| a | b |'
      const headers = rawHeaders.filter((c, idx, arr) => {
        if ((idx === 0 || idx === arr.length - 1) && c === '') return false;
        return true;
      });
      headers.forEach(h => {
        tableHtml += `<th>${h}</th>`;
      });
      tableHtml += '</tr></thead><tbody>';
      i += 2; // Skip header line and separator line

      while (i < lines.length && lines[i].trim().includes('|') && lines[i].trim() !== '') {
        const rowLine = lines[i].trim();
        // Skip extraneous divider lines
        if (/^\|?(\s*:?-+:?\s*\|)+\s*:?-+:?\s*\|?$/.test(rowLine)) {
          i++;
          continue;
        }
        const rawCells = rowLine.split('|').map(c => c.trim());
        const cells = rawCells.filter((c, idx, arr) => {
          if ((idx === 0 || idx === arr.length - 1) && c === '') return false;
          return true;
        });
        tableHtml += '<tr>';
        cells.forEach(cell => {
          tableHtml += `<td>${cell}</td>`;
        });
        tableHtml += '</tr>';
        i++;
      }
      tableHtml += '</tbody></table></div>';
      result.push(tableHtml);
      continue;
    }

    // 2. Headings
    if (line.startsWith('### ')) {
      result.push(`<h3>${line.replace(/^###\s*/, '')}</h3>`);
      i++;
      continue;
    }
    if (line.startsWith('## ')) {
      result.push(`<h2>${line.replace(/^##\s*/, '')}</h2>`);
      i++;
      continue;
    }

    // 3. Bullet Lists (- or • or *)
    if (line.startsWith('- ') || line.startsWith('• ') || line.startsWith('* ')) {
      let listHtml = '<ul>';
      while (i < lines.length && (lines[i].trim().startsWith('- ') || lines[i].trim().startsWith('• ') || lines[i].trim().startsWith('* '))) {
        let itemText = lines[i].trim().replace(/^[-•*]\s*/, '');
        listHtml += `<li>${itemText}</li>`;
        i++;
      }
      listHtml += '</ul>';
      result.push(listHtml);
      continue;
    }

    // 4. Numbered Lists (1. 2. etc.)
    if (/^\d+\.\s/.test(line)) {
      let listHtml = '<ol>';
      while (i < lines.length && /^\d+\.\s/.test(lines[i].trim())) {
        let itemText = lines[i].trim().replace(/^\d+\.\s*/, '');
        listHtml += `<li>${itemText}</li>`;
        i++;
      }
      listHtml += '</ol>';
      result.push(listHtml);
      continue;
    }

    // 5. Horizontal Dividers
    if (line === '---' || line === '***') {
      result.push('<hr class="audit-divider">');
      i++;
      continue;
    }

    // 6. Regular Paragraphs
    if (line.length > 0) {
      let para = [line];
      i++;
      while (i < lines.length && lines[i].trim().length > 0 &&
             !lines[i].trim().includes('|') &&
             !lines[i].trim().startsWith('#') &&
             !lines[i].trim().startsWith('- ') &&
             !lines[i].trim().startsWith('• ') &&
             !lines[i].trim().startsWith('* ') &&
             !/^\d+\.\s/.test(lines[i].trim()) &&
             lines[i].trim() !== '---') {
        para.push(lines[i].trim());
        i++;
      }
      result.push(`<p>${para.join(' ')}</p>`);
      continue;
    }

    i++;
  }

  return result.join('\n');
}

function renderSynthesis(text) {
  const container = document.getElementById('synthesisContainer');
  if (!container) return;

  if (!text) {
    container.innerHTML = "<p>No synthesis findings available.</p>";
    return;
  }

  // Clean title prefix if redundant
  let cleanText = text
    .replace(/### Executive Synthesis: Cross-Launch Distribution Patterns/gi, '')
    .trim();

  container.innerHTML = parseMarkdown(cleanText);
}

function renderLedger() {
  const container = document.getElementById('ledgerContainer');
  if (!container) return;

  container.innerHTML = "";

  // Dynamically load claims from findings.json ledger if present, otherwise fallback
  const claims = (globalFindings?.ledger?.claims && globalFindings.ledger.claims.length > 0)
    ? globalFindings.ledger.claims
    : ledgerClaims;

  claims.forEach(item => {
    const isVerified = item.status === "verified";
    const entry = document.createElement('div');
    entry.className = "receipt-entry";

    const stampText = isVerified ? "VERIFIED" : "UNVERIFIED — FLAGGED";
    const stampClass = isVerified ? "stamp-verified" : "stamp-unverified";
    const transform = getStampTransform(item.claim + (item.context || ""));

    const contextTag = item.context ? `<span style="font-family: var(--font-mono); font-size: 11px; color: var(--ink-muted); margin-right: 6px;">[${item.context}]</span>` : "";
    const corroborationText = item.corroboration || item.detail || "Corroborated by retrieved search evidence";

    entry.innerHTML = `
      <div class="receipt-row">
        <span class="receipt-claim" title="${item.claim}">${contextTag}${item.claim}</span>
        <span class="receipt-dots" aria-hidden="true"></span>
        <div class="receipt-status">
          <span class="stamp ${stampClass}" style="transform: ${transform};">${stampText}</span>
        </div>
      </div>
      <div class="receipt-detail">corroboration: ${corroborationText}</div>
    `;

    container.appendChild(entry);
  });
}

function renderManifest(clients) {
  const container = document.getElementById('manifestList');
  if (!container) return;

  container.innerHTML = "";
  const names = Object.keys(clients);

  names.forEach(name => {
    const data = clients[name];
    const turns = data.turns_taken || 3;
    const tools = (data.tool_results || []);
    const toolCount = tools.length;
    const launch = data.launch_month || "2025-XX";
    const isComplete = data.status === "completed";

    const item = document.createElement('div');
    item.className = "manifest-item";
    item.setAttribute("tabindex", "0");
    item.setAttribute("role", "button");
    item.setAttribute("aria-expanded", "false");

    // Format tool queries HTML for inline expansion
    let toolQueriesHtml = "";
    if (tools.length === 0) {
      toolQueriesHtml = '<div style="color: var(--ink-faint);">No tool queries recorded.</div>';
    } else {
      tools.forEach((t, idx) => {
        const results = (t.result && t.result.results) ? t.result.results : [];
        const resultSnippets = results.slice(0, 2).map(r => `
          <div class="trace-result-item">
            <div class="trace-result-title"><a href="${r.link || '#'}" target="_blank">${r.title || 'Untitled Result'}</a></div>
            <div class="trace-result-snippet">${r.snippet || 'No snippet text.'}</div>
          </div>
        `).join('');

        toolQueriesHtml += `
          <div class="trace-query-block">
            <div class="trace-query-cmd">QUERY #${idx + 1} [${t.tool}]: ${t.arguments || ''}</div>
            ${resultSnippets}
          </div>
        `;
      });
    }

    const summaryText = data.annotated_summary || data.summary || 'Summary unavailable.';
    const formattedSummary = parseMarkdown(summaryText);

    item.innerHTML = `
      <div class="manifest-row">
        <span class="manifest-col-name">${name}</span>
        <span class="manifest-col-date">${launch}</span>
        <span class="manifest-col-turns">${turns} turns</span>
        <span class="manifest-col-queries">${toolCount} queries</span>
        <span class="manifest-col-status ${isComplete ? '' : 'incomplete'}">[${isComplete ? 'COMPLETE' : 'INCOMPLETE'}]</span>
        <span class="manifest-col-toggle" aria-hidden="true">+</span>
      </div>
      <div class="manifest-trace">
        <div class="trace-section-label">Investigation Summary</div>
        <div class="trace-summary">${formattedSummary}</div>
        <div class="trace-section-label" style="margin-top: 10px;">Raw Tool Trace (Serper API)</div>
        ${toolQueriesHtml}
      </div>
    `;

    // Toggle inline expansion on click or Enter key
    const toggleExpand = () => {
      const isExpanded = item.classList.toggle('expanded');
      item.setAttribute("aria-expanded", isExpanded ? "true" : "false");
    };

    item.addEventListener('click', toggleExpand);
    item.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        toggleExpand();
      }
    });

    container.appendChild(item);
  });
}

window.addEventListener('DOMContentLoaded', loadData);
